"""Explain metadata proportions, LIFO and collection ownership for beginners."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1857': ('같은 크기 공책 세 권 중 두 권은 점검 기록, 한 권은 실제 내용에 쓴다면 내용용은 세 권 전부가 아니에요.', '블록 수와 페이지 수, 이 단계의 검사 정보 비용을 계산합니다.', 'order 1 블록 세 개를 각각 두 칸으로 그려 shadow 2칸·origin 2칸·데이터 2칸으로 나누세요.', ['KMSAN은 준비 상태를 담는 shadow와 발생 원인을 담는 origin을 데이터와 별도로 둬요. 검사에 필요한 추가 정보도 메모리를 사용해요. 이 부팅 정책은 같은 크기 블록 세 개를 하나의 묶음으로 처리해요.', '블록은 여러 페이지를 묶은 단위예요. order 0이면 1페이지, order 1이면 2페이지, order 2이면 4페이지예요. 한 페이지가 몇 바이트인지는 환경에 따라 다를 수 있어요.', '같은 order의 첫 블록은 shadow, 둘째는 origin으로 남기고 셋째는 데이터용으로 연결해요. 같은 크기 셋 중 둘이 검사 정보라서 이 묶음의 3분의 2는 검사 정보, 3분의 1은 데이터예요.', 'order 1 블록 세 개라면 전체는 3×2=6페이지예요. shadow 2페이지와 origin 2페이지를 남겨 데이터용으로 반환할 수 있는 양은 한 블록, 즉 2페이지예요. 여섯 페이지 전부가 데이터용으로 돌아가는 것은 아니에요.', '여기서 반환은 페이지 할당기가 일반 용도로 나누어 줄 수 있도록 돌려보내는 처리예요. 검사 정보로 둔 페이지는 데이터용 페이지를 추적하는 역할을 계속 맡아요. 세 블록 전체를 버린다는 뜻이 아니에요.', '이 비율은 이 단계의 세 블록 분배에 대한 계산이에요. 커널 전체에는 다른 관리 구조, 기록 보관소, 할당기 비용도 있어요. 따라서 컴퓨터 전체 메모리 사용량이 언제나 정확히 이 비율이라고 단정하면 안 돼요.'], [('order 1 블록 세 개를 처리하면 데이터용으로 반환할 양은 몇 페이지인가요?', ['블록 세 개의 6페이지 전부예요', '블록 한 개의 2페이지예요'], '정답은 두 번째예요. 한 블록은 2페이지이고 세 블록 중 하나만 데이터용이에요. 나머지 두 블록의 4페이지는 shadow와 origin에 사용해요.'), ('이 세 블록 비율만으로 커널 전체의 추가 메모리 비용을 정확히 계산할 수 있나요?', ['아니요. 이 분배 단계의 비율이며 다른 비용도 있어요', '네. 모든 메모리 사용이 정확히 이 비율만 따라요'], '정답은 첫 번째예요. 2대1 계산은 해당 묶음 안의 검사 정보와 데이터 관계예요. 다른 관리 자료까지 모두 셌다는 뜻은 아니에요.')]), 'os1858': ('카드를 A, B 순서로 쌓으면 맨 위 B부터 꺼내요. 마지막에 넣은 것이 먼저 나오는 저장 방식을 스택이라고 해요.', '작은 고정 스택의 저장 순서와 용량 조건을 이해합니다.', '빈 배열의 0번에 A, 1번에 B를 넣으세요. 사용 개수 2에서 먼저 B를 꺼내는 화살표를 그리세요.', ['smallstack은 블록 위치를 가리키는 포인터를 보관하는 작은 스택이에요. 포인터는 물건 자체가 아니라 물건이 있는 곳을 알려 주는 주소표와 비슷해요. items에는 최대 8개의 포인터를 담아요.', 'index는 사용 중인 항목 수이자 다음에 넣을 칸의 번호예요. order는 보관 블록의 페이지 크기 단계를 나타내요. 포인터 여덟 개라는 용량을 데이터 여덟 바이트나 페이지 여덟 개와 혼동하지 마세요.', 'push는 넣기예요. items[index]에 새 포인터를 쓰고 index를 1 늘려요. 빈 상태에서 A를 넣으면 0번 칸에 A, index는 1이에요. B를 넣으면 1번 칸에 B, index는 2가 돼요.', 'pop은 꺼내기예요. 먼저 index를 1 줄인 뒤 그 칸을 읽어요. 따라서 두 항목 상태에서 index가 1이 되고 1번의 B를 먼저 꺼내요. 마지막 입력이 먼저 나오는 규칙을 LIFO라고 불러요.', '먼저 들어온 A부터 나오는 줄서기 방식 FIFO와 달라요. 자료구조 이름만 외우기보다 index가 어느 시점에 늘고 줄어드는지 숫자로 따라가 보세요. 실제 블록 내용 자체를 배열에 복사해 쌓는 것도 아니에요.', 'push는 index가 8인지 경고하지만 용량을 자동으로 늘리거나 반환문으로 쓰기를 취소하지 않아요. KMSAN 경고는 검사를 끄고 설정에 따라 실행을 중단할 수도 있으나, 계속 실행되면 후속 쓰기가 있어요. 호출자는 용량 안에서 넣어야 하며 실습은 유효한 두 항목만 사용해요.'], [('빈 스택에 A 다음 B를 넣으면 첫 pop은 무엇인가요?', ['먼저 넣은 A예요', '마지막에 넣은 B예요'], '정답은 두 번째예요. index 2를 1로 줄인 뒤 1번 칸을 읽으므로 B예요. A부터 나오는 줄서기와 다른 규칙이에요.'), ('용량 경고가 있으면 push가 자동 확장되거나 안전하게 쓰기를 생략하나요?', ['아니요. 그런 확장이나 반환 분기는 없어요', '네. 어떤 개수든 자동으로 공간을 늘려요'], '정답은 첫 번째예요. 고정 배열은 8칸이에요. 경고 뒤 실행이 계속되면 쓰기 코드가 있으므로 호출하는 쪽이 용량을 지켜야 해요.')]), 'os1859': ('주소 쪽지를 꺼낼 때 손에 복사해 둔 뒤 보관 칸을 비워요. 보관 칸이 비었다고 손에 든 주소나 그곳의 물건까지 없어지는 것은 아니에요.', 'pop의 감소·읽기·칸 비우기 순서와 빈 스택의 제한을 이해합니다.', 'A와 B가 있는 스택에서 B를 ret에 옮겨 적고 1번 칸을 NULL로 바꾸세요. 남은 개수는 1이에요.', ['smallstack_pop은 먼저 index가 0인지 경고해요. 0이면 저장한 항목이 하나도 없다는 뜻이에요. 정상 사용에서는 꺼낼 항목이 있는지 호출하는 쪽이 먼저 보장해야 해요.', '항목이 있으면 index를 1 줄여 마지막 사용 칸의 번호로 만들어요. index 2에서는 1이 되고 items[1]을 읽어요. 먼저 줄이는 이유는 2가 다음 빈 칸이고 마지막 항목은 1번이기 때문이에요.', '읽은 포인터를 ret에 저장하고 같은 items 칸에는 NULL을 써요. NULL은 그 보관 칸에 포인터가 없다는 표시예요. 마지막으로 ret를 반환해 호출자가 꺼낸 블록을 계속 다룰 수 있게 해요.', 'items[1]을 비워도 ret에 보관한 포인터는 그대로예요. 블록 메모리를 해제하는 코드가 아니고 스택에서 해당 항목을 제거하는 코드예요. 남은 항목과 꺼낸 항목을 구별해 보세요.', '빈 스택일 때 자동으로 NULL을 반환하는 if-return은 없어요. 경고 뒤 실행이 계속되면 정수 index가 0에서 -1로 줄고 배열 범위를 벗어난 칸을 읽게 돼요. 이는 정상 사용법이 아니므로 실제로 실행해 볼 실습으로 삼지 않아요.', 'KMSAN_WARN_ON은 단순히 글만 출력하는 경고가 아니라 검사 비활성화와 설정에 따른 중단도 할 수 있어요. 그렇더라도 빈 pop을 안전한 실패 반환으로 바꿔 주는 API는 아니에요. 종이 실습에서는 유효한 항목을 꺼내는 순서를 확인하세요.'], [('정상 pop에서 포인터를 ret에 보관한 뒤 원래 배열 칸은 어떻게 하나요?', ['예전 포인터를 반드시 그대로 남겨요', 'NULL로 비워요'], '정답은 두 번째예요. 코드는 읽기→칸 비우기→ret 반환 순서예요. 스택 칸을 비워도 반환할 포인터와 실제 블록은 그 때문에 없어지지 않아요.'), ('빈 스택에서도 pop을 부르면 안전하게 NULL이 돌아온다고 보장하나요?', ['아니요. 호출자가 빈 상태에서 꺼내지 않도록 해야 해요', '네. 경고가 있으므로 언제나 안전한 NULL 반환이에요'], '정답은 첫 번째예요. 빈 상태를 위한 반환문이 없고 계속 실행되면 index 감소와 배열 읽기로 이어져요. 경고 존재와 안전한 오류 처리는 같은 뜻이 아니에요.')]), 'os1860': ('쌓아 둔 카드 세 장을 위에서부터 꺼내 데이터, 상태표, 원인표 역할을 붙여 봐요. 넣은 순서와 맡는 역할은 꺼내는 순서에 따라 달라져요.', '세 번의 pop과 검사 정보 연결·페이지 반환 순서를 이해합니다.', 'A→B→C 순서로 넣고 C는 page, B는 shadow, A는 origin이라고 적은 뒤 연결→반환 화살표를 그리세요.', ['do_collection은 collect라는 작은 스택에서 남은 블록을 묶어 처리해요. while (collect.index >= 3)은 적어도 세 항목이 있을 때만 반복하라는 뜻이에요. 한두 개만 남으면 이 반복은 멈춰요.', '첫 pop 결과는 page에 넣어요. 이 블록이 데이터용 역할을 맡아요. 두 번째 pop은 준비 상태용 shadow, 세 번째 pop은 원인 기록용 origin에 넣어요. 세 번 모두 같은 스택에서 꺼내요.', '빈 스택에 A, B, C를 차례로 넣었다면 꺼내는 순서는 C, B, A예요. 따라서 page는 C, shadow는 B, origin은 A예요. 먼저 넣었다는 이유만으로 A가 데이터라고 판단하면 안 돼요.', '다음 kmsan_setup_meta 호출이 데이터 페이지와 두 검사 정보 블록을 연결해요. collect.order는 각 블록의 페이지 수 단계를 알려 줘요. 이 처리에서는 같은 order의 블록들이 모여 있다는 조건이 필요해요.', '연결을 마친 다음 __free_pages_core(page, collect.order, MEMINIT_EARLY)를 호출해 데이터 블록을 페이지 할당기 쪽으로 반환해요. MEMINIT_EARLY는 이 반환이 초기 메모리 준비 단계라는 정보를 전달해요. 이 함수는 반환값만 주는 앞의 helper와 달리 실제 반환 함수를 직접 호출해요.', '세 항목을 처리하면 개수가 3 줄어요. 여섯 개라면 두 묶음을 처리하고, 네 개라면 한 묶음을 처리한 뒤 하나가 남아요. shadow와 origin 블록까지 이 자리에서 각각 일반 페이지로 반환하는 것이 아니라 데이터의 검사 정보로 연결해 둬요.'], [('A, B, C를 차례로 넣은 스택에서 이 함수가 데이터용으로 고르는 블록은 무엇인가요?', ['처음 넣은 A예요', '마지막에 넣은 C예요'], '정답은 두 번째예요. 첫 pop을 page에 넣는데 LIFO이므로 C가 먼저 나와요. 그다음 B는 shadow, A는 origin이 돼요.'), ('데이터 블록을 __free_pages_core로 반환하기 전에 무엇을 하나요?', ['데이터에 shadow와 origin을 연결해요', '검사 정보 없이 즉시 반환해요'], '정답은 첫 번째예요. kmsan_setup_meta가 먼저이고 반환 호출이 뒤예요. 두 검사 정보 블록은 데이터 페이지를 추적하는 데 쓰이므로 순서와 역할을 함께 읽으세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_460.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
